-- Generated by generate-views.ts from public.replication_canary. Regenerate after a migration changes its columns.
CREATE OR REPLACE VIEW goodparty_data_catalog.gp_api_mirror_dms.replication_canary
COMMENT 'Current state of public.replication_canary: the latest change per primary key in dms_cdc_change, deletes removed. TOASTable columns an update left out are carried from the previous change.'
AS
WITH reload AS (
  SELECT max(reloaded_at) AS reloaded_at FROM goodparty_data_catalog.gp_api_mirror_dms.dms_cdc_reload WHERE source_table = 'replication_canary'
),
changes AS (
  SELECT c.pk, c.op, c.seq, c.ingested_at, c.row_image, CASE WHEN c.op = 'update' THEN json_object_keys(c.row_image) END AS image_columns
  FROM goodparty_data_catalog.gp_api_mirror_dms.dms_cdc_change c CROSS JOIN reload r
  WHERE c.source_schema = 'public' AND c.source_table = 'replication_canary'
    AND (r.reloaded_at IS NULL OR c.ingested_at >= r.reloaded_at)
),
latest AS (
  SELECT
    max_by(op, seq) AS _dms_op,
    max(ingested_at) AS _dms_ingested_at,
    max_by(CAST(row_image:['id']::string AS INT), seq) AS `id`,
    max_by(CAST(concat(regexp_replace(row_image:['written_at']::string, '(Z|[+-]00(:?00)?)$', ''), '+00:00') AS TIMESTAMP), seq) AS `written_at`
  FROM changes
  GROUP BY pk
)
SELECT `id`, `written_at`, _dms_ingested_at
FROM latest
WHERE _dms_op <> 'delete';
